        let mismatches = Mismatches("portShiftedRightWhereOtherwiseU32ConstantBits")
        let otherwiseInputs = Inputs.vectors(H.Vector.self, seed: 0x4A31_45E7_AF97_0D57)
        let maskInputs = Inputs.masks(H.Mask.self, seed: 0x4A31_44E7_AF97_0BA4)
        let aInputs = Inputs.vectors(H.Vector.self, seed: 0x4A31_47E7_AF97_10BD)
        for (otherwise, mask, a) in mixedTriples(
            otherwiseInputs,
            maskInputs,
            aInputs,
            seed: 0x8C7B_5680_399F_91D1
        ) {
            mismatches.check(
                portShiftedRightWhereOtherwiseU32ConstantBits(a, where: mask, otherwise: otherwise),
                highwayShiftedRightWhereOtherwiseU32ConstantBits(
                    a,
                    where: mask,
                    otherwise: otherwise
                ),
                "otherwise: \(describe(otherwise)), mask: \(describe(mask)), a: \(describe(a))"
